<section class="auth-card"><p class="eyebrow">Account recovery</p><h1>Choose a new password</h1><form method="post" action="/password/reset" class="form-stack"><?= csrf_field() ?><input type="hidden" name="token" value="<?= e($token) ?>"><label>New password<input type="password" name="password" required minlength="12" autocomplete="new-password"></label><label>Confirm new password<input type="password" name="password_confirmation" required autocomplete="new-password"></label><button class="button primary">Update password</button></form></section>
